#[cfg(feature = "presets")]
impl Registry {
    fn get(&self, id: String) -> Option<Preset> {
        self.inner.lock().unwrap().get(&id).map(|v| v.clone().into())
    }

    fn summaries(&self) -> Vec<PresetSummary> {
        self.inner
            .lock()
            .unwrap()
            .summaries()
            .into_iter()
            .map(Into::into)
            .collect()
    }

    fn len(&self) -> usize {
        self.inner.lock().unwrap().len()
    }

    fn is_empty(&self) -> bool {
        self.inner.lock().unwrap().is_empty()
    }

    fn sample_bytes(&self, preset_id: String, name: String) -> Option<Vec<u8>> {
        self.inner
            .lock()
            .unwrap()
            .sample_bytes(&preset_id, &name)
            .map(Into::into)
    }

    fn extend_from_dir(&self, dir: String) -> Result<usize, Error> {
        let result = self
            .inner
            .lock()
            .unwrap()
            .extend_from_dir(std::path::Path::new(&dir))
            .map_err(|e| {
                magnus::Error::new(
                    unsafe { Ruby::get_unchecked() }.exception_runtime_error(),
                    e.to_string(),
                )
            })?;
        Ok(result)
    }
}

