fn classify_chunks_owned(result: magnus::Value, config: magnus::Value) -> Result<ExtractedDocument, Error> {
    let result_core: xberg::ExtractedDocument = {
        let binding_val: ExtractedDocument = ExtractedDocument::try_convert(result).map_err(|e| {
            magnus::Error::new(
                unsafe { Ruby::get_unchecked() }.exception_runtime_error(),
                e.to_string(),
            )
        })?;
        binding_val.into()
    };
    let config_core: xberg::ChunkClassificationConfig = {
        let binding_val: ChunkClassificationConfig = ChunkClassificationConfig::try_convert(config).map_err(|e| {
            magnus::Error::new(
                unsafe { Ruby::get_unchecked() }.exception_runtime_error(),
                e.to_string(),
            )
        })?;
        binding_val.into()
    };
    let async_result = alef_magnus_run_without_gvl(move || -> Result<_, String> {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|e| e.to_string())?;
        rt.block_on(async { xberg::text::classification::classify_chunks_owned(result_core, &config_core).await })
            .map_err(|e| e.to_string())
    });
    let result = async_result
        .map_err(|message| magnus::Error::new(unsafe { Ruby::get_unchecked() }.exception_runtime_error(), message))?;
    Ok(result.into())
}

