#[async_trait::async_trait]
impl xberg::DocumentExtractor for RbDocumentExtractorBridge {
    async fn extract(
        &self,
        input: xberg::ExtractInput,
        config: &xberg::ExtractionConfig,
    ) -> std::result::Result<xberg::ExtractedDocument, xberg::XbergError> {
        let input_owned = input;
        let config_owned = config.clone();
        let dispatcher = self.runtime_dispatcher.clone();
        let callback = move |ruby: &magnus::Ruby,
                             value: magnus::Value|
              -> std::result::Result<xberg::ExtractedDocument, xberg::XbergError> {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>(
                "extract",
                (
                    {
                        use magnus::IntoValue;
                        ExtractInput::from(input_owned.clone()).into_value_with(&ruby)
                    },
                    {
                        use magnus::IntoValue;
                        ExtractionConfig::from(config_owned.clone()).into_value_with(&ruby)
                    },
                ),
            ) {
                Ok(v) => v,
                Err(e) => {
                    return Err(xberg::XbergError::Other(format!("Ruby method 'extract' failed: {}", e)));
                }
            }; // Native-object return: the binding struct's `TryConvert` accepts the host's native wrapped
            // object (and still a Hash/JSON via `to_json`); `From<ExtractedDocument>` yields core.
            <ExtractedDocument as magnus::TryConvert>::try_convert(val)
                .map(Into::into)
                .map_err(|e| xberg::XbergError::Other(format!("Failed to convert Ruby 'extract' return value: {}", e)))
        };
        match tokio::task::spawn_blocking(move || dispatcher.dispatch(callback)).await {
            Ok(Ok(result)) => result,
            Ok(Err(error)) => Err(xberg::XbergError::Other(format!(
                "Ruby runtime dispatcher failed for method 'extract': {}",
                error
            ))),
            Err(error) => Err(xberg::XbergError::Other(format!(
                "Ruby runtime dispatcher task failed for method 'extract': {}",
                error
            ))),
        }
    }

    fn supported_mime_types(&self) -> &[&str] {
        let __types: Vec<String> = {
            let callback = move |ruby: &magnus::Ruby, value: magnus::Value| -> Vec<String> {
                let val: magnus::Value = match value.funcall::<_, _, magnus::Value>("supported_mime_types", ()) {
                    Ok(v) => v,
                    Err(e) => {
                        // This method's Rust signature is infallible, so a Ruby exception cannot
                        // propagate. Log before substituting the default — a silent default is
                        // indistinguishable from a real result to the caller.
                        tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "supported_mime_types", error = %e, "host callback raised; returning default");
                        return Default::default();
                    }
                };
                <Vec<String> as magnus::TryConvert>::try_convert(val).unwrap_or_else(|e| {
                tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "supported_mime_types", error = %e, "host returned an unconvertible value; returning default");
                Default::default()
            })
            };
            match magnus::Ruby::get() {
                Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
                Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                    Ok(result) => result,
                    Err(error) => {
                        tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "supported_mime_types", %error, "Ruby runtime dispatcher failed; returning default");
                        Default::default()
                    }
                },
            }
        };
        let __strs: Vec<&'static str> = __types
            .into_iter()
            .map(|s| -> &'static str { Box::leak(s.into_boxed_str()) })
            .collect();
        Box::leak(__strs.into_boxed_slice())
    }

    fn priority(&self) -> i32 {
        if !(self.has_priority) {
            return RbDocumentExtractorBridgeDefaultPriority(self).priority();
        }
        let callback = move |ruby: &magnus::Ruby, value: magnus::Value| -> i32 {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>("priority", ()) {
                Ok(v) => v,
                Err(e) => {
                    // This method's Rust signature is infallible, so a Ruby exception cannot
                    // propagate. Log before substituting the default — a silent default is
                    // indistinguishable from a real result to the caller.
                    tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "priority", error = %e, "host callback raised; returning default");
                    return Default::default();
                }
            };
            <i32 as magnus::TryConvert>::try_convert(val).unwrap_or_else(|e| {
                tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "priority", error = %e, "host returned an unconvertible value; returning default");
                Default::default()
            })
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => {
                    tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "priority", %error, "Ruby runtime dispatcher failed; returning default");
                    Default::default()
                }
            },
        }
    }

    fn can_handle(&self, _path: &std::path::Path, _mime_type: &str) -> bool {
        if !(self.has_can_handle) {
            return RbDocumentExtractorBridgeDefaultCanHandle(self).can_handle(_path, _mime_type);
        }
        let _path = _path.to_path_buf();
        let _mime_type = _mime_type.to_string();
        let callback = move |ruby: &magnus::Ruby, value: magnus::Value| -> bool {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>(
                "can_handle",
                (
                    ruby.str_new(<_ as AsRef<std::path::Path>>::as_ref(&_path).to_string_lossy().as_ref())
                        .as_value(),
                    ruby.str_new(AsRef::<str>::as_ref(&_mime_type)).as_value(),
                ),
            ) {
                Ok(v) => v,
                Err(e) => {
                    // This method's Rust signature is infallible, so a Ruby exception cannot
                    // propagate. Log before substituting the default — a silent default is
                    // indistinguishable from a real result to the caller.
                    tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "can_handle", error = %e, "host callback raised; returning default");
                    return Default::default();
                }
            };
            <bool as magnus::TryConvert>::try_convert(val).unwrap_or_else(|e| {
                tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "can_handle", error = %e, "host returned an unconvertible value; returning default");
                Default::default()
            })
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => {
                    tracing::warn!(wrapper = "RbDocumentExtractorBridge", method = "can_handle", %error, "Ruby runtime dispatcher failed; returning default");
                    Default::default()
                }
            },
        }
    }
}

