impl xberg::plugins::Plugin for RbDocumentExtractorBridgeDefaultCanHandle<'_> {
    fn name(&self) -> &str {
        xberg::plugins::Plugin::name(self.0)
    }

    fn version(&self) -> String {
        xberg::plugins::Plugin::version(self.0)
    }

    fn initialize(&self) -> std::result::Result<(), xberg::XbergError> {
        xberg::plugins::Plugin::initialize(self.0)
    }

    fn shutdown(&self) -> std::result::Result<(), xberg::XbergError> {
        xberg::plugins::Plugin::shutdown(self.0)
    }
}
#[async_trait::async_trait]
impl xberg::DocumentExtractor for RbDocumentExtractorBridgeDefaultCanHandle<'_> {
    async fn extract(
        &self,
        input: xberg::ExtractInput,
        config: &xberg::ExtractionConfig,
    ) -> std::result::Result<xberg::ExtractedDocument, xberg::XbergError> {
        xberg::DocumentExtractor::extract(self.0, input, config).await
    }
    fn supported_mime_types(&self) -> &[&str] {
        xberg::DocumentExtractor::supported_mime_types(self.0)
    }
    fn priority(&self) -> i32 {
        xberg::DocumentExtractor::priority(self.0)
    }
}

pub fn register_document_extractor(rb_obj: magnus::Value, name: String) -> Result<(), magnus::Error> {
    let required_methods = ["extract", "supported_mime_types"];
    for method in &required_methods {
        if !rb_obj.respond_to(*method, false).unwrap_or(false) {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            return Err(magnus::Error::new(
                ruby.exception_runtime_error(),
                format!("Backend missing required method: {}", method),
            ));
        }
    }
    let wrapper = RbDocumentExtractorBridge::new(rb_obj, name)?;
    let arc: Arc<dyn xberg::DocumentExtractor> = Arc::new(wrapper);

    xberg::plugins::registry::get_document_extractor_registry()
        .write()
        .register(arc)
        .map_err(|e| {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            magnus::Error::new(ruby.exception_runtime_error(), format!("register failed: {}", e))
        })?;
    Ok(())
}

pub fn unregister_document_extractor(name: String) -> Result<(), magnus::Error> {
    xberg::plugins::document_extractor::unregister_document_extractor(&name).map_err(|e| {
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        magnus::Error::new(ruby.exception_runtime_error(), format!("{}", e))
    })
}

pub fn clear_document_extractors() -> Result<(), magnus::Error> {
    xberg::plugins::document_extractor::clear_document_extractors().map_err(|e| {
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        magnus::Error::new(ruby.exception_runtime_error(), format!("{}", e))
    })
}

#[allow(unused_imports)]
use magnus::TryConvert as _;
#[allow(unused_imports)]
use magnus::value::InnerValue as _;
type RbEmbeddingBackendBridgeRuntimeJob = Box<dyn FnOnce(&magnus::Ruby, magnus::Value) + Send + 'static>;

#[derive(Clone)]
struct RbEmbeddingBackendBridgeRuntimeDispatcher {
    sender: std::sync::mpsc::SyncSender<RbEmbeddingBackendBridgeRuntimeJob>,
}

impl RbEmbeddingBackendBridgeRuntimeDispatcher {
    const QUEUE_CAPACITY: usize = 64;

    fn new(ruby: &magnus::Ruby, rb_obj: magnus::Value) -> Result<Self, magnus::Error> {
        use magnus::value::InnerValue as _;

        let (sender, receiver) = std::sync::mpsc::sync_channel(Self::QUEUE_CAPACITY);
        let inner = magnus::value::Opaque::from(rb_obj);
        let thread = ruby.thread_create_from_fn(move |ruby| {
            while let Ok(job) = Self::recv_without_gvl(&receiver) {
                let value = inner.get_inner_with(ruby);
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    job(ruby, value);
                }));
            }
        });

        // The active Ruby thread is VM-rooted; its ivar keeps the host object live
        // until every bridge sender is gone and the dispatcher exits.
        use magnus::Object as _;
        thread.ivar_set("__alef_trait_bridge_host", rb_obj)?;
        Ok(Self { sender })
    }

    fn dispatch<T, F>(&self, callback: F) -> Result<T, String>
    where
        T: Send + 'static,
        F: FnOnce(&magnus::Ruby, magnus::Value) -> T + Send + 'static,
    {
        let (result_sender, result_receiver) = std::sync::mpsc::sync_channel(1);
        self.sender
            .send(Box::new(move |ruby, value| {
                let result = callback(ruby, value);
                let _ = result_sender.send(result);
            }))
            .map_err(|_| "Ruby runtime dispatcher is not available".to_string())?;
        result_receiver
            .recv()
            .map_err(|_| "Ruby runtime dispatcher callback did not return".to_string())
    }

    fn recv_without_gvl(
        receiver: &std::sync::mpsc::Receiver<RbEmbeddingBackendBridgeRuntimeJob>,
    ) -> Result<RbEmbeddingBackendBridgeRuntimeJob, std::sync::mpsc::RecvError> {
        struct ReceiveState<'a> {
            receiver: &'a std::sync::mpsc::Receiver<RbEmbeddingBackendBridgeRuntimeJob>,
            result: Option<Result<RbEmbeddingBackendBridgeRuntimeJob, std::sync::mpsc::RecvError>>,
        }

        unsafe extern "C" fn receive(data: *mut std::ffi::c_void) -> *mut std::ffi::c_void {
            // SAFETY: the state pointer remains valid until Ruby returns from the
            // without-GVL callback on this same Ruby-created thread.
            let state = unsafe { &mut *(data as *mut ReceiveState<'_>) };
            state.result = Some(state.receiver.recv());
            std::ptr::null_mut()
        }

        let mut state = ReceiveState { receiver, result: None };
        // SAFETY: this runs on the dedicated Ruby-created dispatcher thread. The
        // callback touches only Rust channel state and the sender disconnect wakes it.
        unsafe {
            rb_sys::rb_thread_call_without_gvl(
                Some(receive),
                &mut state as *mut ReceiveState<'_> as *mut std::ffi::c_void,
                None,
                std::ptr::null_mut(),
            );
        }
        state.result.unwrap_or_else(|| Err(std::sync::mpsc::RecvError))
    }
}

/// Wrapper that bridges a foreign Rb object to the `EmbeddingBackend` trait.
pub struct RbEmbeddingBackendBridge {
    inner: magnus::value::Opaque<magnus::Value>,
    cached_name: String,
    has_initialize: bool,
    has_shutdown: bool,
    runtime_dispatcher: RbEmbeddingBackendBridgeRuntimeDispatcher,
}

impl std::fmt::Debug for RbEmbeddingBackendBridge {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "RbEmbeddingBackendBridge")
    }
}

impl RbEmbeddingBackendBridge {
    /// Create a new bridge wrapping a Ruby object.
    /// Validates that the Ruby object responds to all required methods.
    pub fn new(rb_obj: magnus::Value, name: String) -> Result<Self, magnus::Error> {
        // SAFETY: constructors are called by generated Magnus registration functions.
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        if !rb_obj.respond_to("dimensions", false).unwrap_or(false) {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            return Err(magnus::Error::new(
                ruby.exception_runtime_error(),
                format!("Ruby object missing required method: {}", "dimensions"),
            ));
        }
        if !rb_obj.respond_to("embed", false).unwrap_or(false) {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            return Err(magnus::Error::new(
                ruby.exception_runtime_error(),
                format!("Ruby object missing required method: {}", "embed"),
            ));
        }
        let runtime_dispatcher = RbEmbeddingBackendBridgeRuntimeDispatcher::new(&ruby, rb_obj)?;

        Ok(Self {
            inner: magnus::value::Opaque::from(rb_obj),
            cached_name: name,
            runtime_dispatcher,
            has_initialize: rb_obj.respond_to("initialize", false).unwrap_or(false),
            has_shutdown: rb_obj.respond_to("shutdown", false).unwrap_or(false),
        })
    }
}

impl xberg::plugins::Plugin for RbEmbeddingBackendBridge {
    fn name(&self) -> &str {
        &self.cached_name
    }

    fn version(&self) -> String {
        let callback = move |ruby: &magnus::Ruby, value: magnus::Value| -> String {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>("version", ()) {
                Ok(v) => v,
                Err(e) => {
                    // This method's Rust signature is infallible, so a Ruby exception cannot
                    // propagate. Log before substituting the default — a silent default is
                    // indistinguishable from a real result to the caller.
                    tracing::warn!(wrapper = "RbEmbeddingBackendBridge", method = "version", error = %e, "host callback raised; returning default");
                    return Default::default();
                }
            };
            <String as magnus::TryConvert>::try_convert(val).unwrap_or_else(|e| {
                tracing::warn!(wrapper = "RbEmbeddingBackendBridge", method = "version", error = %e, "host returned an unconvertible value; returning default");
                Default::default()
            })
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => {
                    tracing::warn!(wrapper = "RbEmbeddingBackendBridge", method = "version", %error, "Ruby runtime dispatcher failed; returning default");
                    Default::default()
                }
            },
        }
    }

    fn initialize(&self) -> std::result::Result<(), xberg::XbergError> {
        if !(self.has_initialize) {
            return Ok(());
        }
        let callback = move |ruby: &magnus::Ruby, value: magnus::Value| -> std::result::Result<(), xberg::XbergError> {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>("initialize", ()) {
                Ok(v) => v,
                Err(e) => {
                    return Err(xberg::XbergError::Other(format!(
                        "Ruby method 'initialize' failed: {}",
                        e
                    )));
                }
            };
            let _ = val;
            Ok(())
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => Err(xberg::XbergError::Other(format!(
                    "Ruby runtime dispatcher failed for method 'initialize': {}",
                    error
                ))),
            },
        }
    }

    fn shutdown(&self) -> std::result::Result<(), xberg::XbergError> {
        if !(self.has_shutdown) {
            return Ok(());
        }
        let callback = move |ruby: &magnus::Ruby, value: magnus::Value| -> std::result::Result<(), xberg::XbergError> {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>("shutdown", ()) {
                Ok(v) => v,
                Err(e) => {
                    return Err(xberg::XbergError::Other(format!(
                        "Ruby method 'shutdown' failed: {}",
                        e
                    )));
                }
            };
            let _ = val;
            Ok(())
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => Err(xberg::XbergError::Other(format!(
                    "Ruby runtime dispatcher failed for method 'shutdown': {}",
                    error
                ))),
            },
        }
    }
}

#[async_trait::async_trait]
impl xberg::EmbeddingBackend for RbEmbeddingBackendBridge {
    fn dimensions(&self) -> usize {
        let callback = move |ruby: &magnus::Ruby, value: magnus::Value| -> usize {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>("dimensions", ()) {
                Ok(v) => v,
                Err(e) => {
                    // This method's Rust signature is infallible, so a Ruby exception cannot
                    // propagate. Log before substituting the default — a silent default is
                    // indistinguishable from a real result to the caller.
                    tracing::warn!(wrapper = "RbEmbeddingBackendBridge", method = "dimensions", error = %e, "host callback raised; returning default");
                    return Default::default();
                }
            };
            <usize as magnus::TryConvert>::try_convert(val).unwrap_or_else(|e| {
                tracing::warn!(wrapper = "RbEmbeddingBackendBridge", method = "dimensions", error = %e, "host returned an unconvertible value; returning default");
                Default::default()
            })
        };
        match magnus::Ruby::get() {
            Ok(ruby) => callback(&ruby, self.inner.get_inner_with(&ruby)),
            Err(_) => match self.runtime_dispatcher.dispatch(callback) {
                Ok(result) => result,
                Err(error) => {
                    tracing::warn!(wrapper = "RbEmbeddingBackendBridge", method = "dimensions", %error, "Ruby runtime dispatcher failed; returning default");
                    Default::default()
                }
            },
        }
    }

    async fn embed(&self, texts: Vec<String>) -> std::result::Result<Vec<Vec<f32>>, xberg::XbergError> {
        let texts_owned = texts;
        let dispatcher = self.runtime_dispatcher.clone();
        let callback = move |ruby: &magnus::Ruby,
                             value: magnus::Value|
              -> std::result::Result<Vec<Vec<f32>>, xberg::XbergError> {
            let val: magnus::Value = match value.funcall::<_, _, magnus::Value>(
                "embed",
                (serde_json::to_string(&texts_owned)
                    .ok()
                    .map(|s| ruby.str_new(s.as_str()).as_value())
                    .unwrap_or_else(|| ruby.qnil().as_value()),),
            ) {
                Ok(v) => v,
                Err(e) => {
                    return Err(xberg::XbergError::Other(format!("Ruby method 'embed' failed: {}", e)));
                }
            };
            <Vec<Vec<f32>> as magnus::TryConvert>::try_convert(val)
                .map_err(|e| xberg::XbergError::Other(format!("Failed to convert Ruby 'embed' return value: {}", e)))
        };
        match tokio::task::spawn_blocking(move || dispatcher.dispatch(callback)).await {
            Ok(Ok(result)) => result,
            Ok(Err(error)) => Err(xberg::XbergError::Other(format!(
                "Ruby runtime dispatcher failed for method 'embed': {}",
                error
            ))),
            Err(error) => Err(xberg::XbergError::Other(format!(
                "Ruby runtime dispatcher task failed for method 'embed': {}",
                error
            ))),
        }
    }
}

pub fn register_embedding_backend(rb_obj: magnus::Value, name: String) -> Result<(), magnus::Error> {
    let required_methods = ["dimensions", "embed"];
    for method in &required_methods {
        if !rb_obj.respond_to(*method, false).unwrap_or(false) {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            return Err(magnus::Error::new(
                ruby.exception_runtime_error(),
                format!("Backend missing required method: {}", method),
            ));
        }
    }
    let wrapper = RbEmbeddingBackendBridge::new(rb_obj, name)?;
    let arc: Arc<dyn xberg::EmbeddingBackend> = Arc::new(wrapper);

    xberg::plugins::registry::get_embedding_backend_registry()
        .write()
        .register(arc)
        .map_err(|e| {
            let ruby = unsafe { magnus::Ruby::get_unchecked() };
            magnus::Error::new(ruby.exception_runtime_error(), format!("register failed: {}", e))
        })?;
    Ok(())
}

pub fn unregister_embedding_backend(name: String) -> Result<(), magnus::Error> {
    xberg::plugins::embedding_backend::unregister_embedding_backend(&name).map_err(|e| {
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        magnus::Error::new(ruby.exception_runtime_error(), format!("{}", e))
    })
}

pub fn clear_embedding_backends() -> Result<(), magnus::Error> {
    xberg::plugins::embedding_backend::clear_embedding_backends().map_err(|e| {
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        magnus::Error::new(ruby.exception_runtime_error(), format!("{}", e))
    })
}

