pub fn unregister_tokenizer_backend(name: String) -> Result<(), magnus::Error> {
    xberg::plugins::tokenizer_backend::unregister_tokenizer_backend(&name).map_err(|e| {
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        magnus::Error::new(ruby.exception_runtime_error(), format!("{}", e))
    })
}

pub fn clear_tokenizer_backends() -> Result<(), magnus::Error> {
    xberg::plugins::tokenizer_backend::clear_tokenizer_backends().map_err(|e| {
        let ruby = unsafe { magnus::Ruby::get_unchecked() };
        magnus::Error::new(ruby.exception_runtime_error(), format!("{}", e))
    })
}

